diff --git a/libheif/image/pixelimage.cc b/libheif/image/pixelimage.cc
index 8120071..145a25c 100644
--- a/libheif/image/pixelimage.cc
+++ b/libheif/image/pixelimage.cc
@@ -640,6 +640,27 @@ Error HeifPixelImage::extend_to_size_with_zero(uint32_t width, uint32_t height,
     return Error::Ok;
   }

+  // Preflight: a Cb/Cr plane is subsampled from the logical size, so growing the
+  // logical image does not necessarily grow every plane by the same amount. Compare
+  // the old and new subsampled extents for each component directly, the same way the
+  // logical size is compared above, so that a plane could never shrink even if the
+  // subsampled rounding behaved unexpectedly for some combination of sizes.
+  for (const auto& component : m_storage) {
+    uint32_t old_subsampled_width, old_subsampled_height;
+    get_subsampled_size(m_width, m_height, component.m_channel, m_chroma,
+                        &old_subsampled_width, &old_subsampled_height);
+
+    uint32_t new_subsampled_width, new_subsampled_height;
+    get_subsampled_size(width, height, component.m_channel, m_chroma,
+                        &new_subsampled_width, &new_subsampled_height);
+
+    if (new_subsampled_width < old_subsampled_width || new_subsampled_height < old_subsampled_height) {
+      return Error{heif_error_Usage_error,
+                   heif_suberror_Invalid_parameter_value,
+                   "Cannot extend an image to a size smaller than an existing plane."};
+    }
+  }
